47	interface PricingRow {
48	  code?: string;
49	  currency?: string | null;
50	  numberLocale?: string | null;
51	  driverAgeBands?: unknown[] | null;
52	  vehicleAgeBands?: unknown[] | null;
53	}
54	
55	/**
56	 * Pure: the values a country row is missing, taken from the defaults. Only rows that predate US-02
57	 * (currency or numberLocale missing) are backfilled; once a row has both, it is never touched, so bands
58	 * an editor emptied on purpose stay empty. Within a pre-US-02 row, only empty bands are filled.
59	 */
60	export function pricingPatch(row: PricingRow): Record<string, unknown> {
61	  const patch: Record<string, unknown> = {};
62	  if (row.currency && row.numberLocale) return patch;
63	  const defaults = PRICING_DEFAULTS[row.code ?? ''];
64	  if (!row.currency && defaults) patch.currency = defaults.currency;
65	  if (!row.numberLocale && defaults) patch.numberLocale = defaults.numberLocale;
66	  if (!row.driverAgeBands?.length) patch.driverAgeBands = DRIVER_BANDS;
67	  if (!row.vehicleAgeBands?.length) patch.vehicleAgeBands = VEHICLE_BANDS;
68	  return patch;
69	}
70	
71	const BAND_KEYS = ['driverAgeBands', 'vehicleAgeBands'];
72	
73	/**
74	 * Existing databases get currency, locale and bands only on rows that predate US-02.
75	 * Publication state is never changed: scalars are written at the DB layer on each row (draft and published
76	 * alike, like backfillLegalAge). The db layer does not manage components, so the bands are written with the
77	 * Document Service on the same version only (`draft` or `published` as the row is); that updates that
78	 * version in place and never publishes a draft.
79	 */
80	export async function backfillCountryPricing(strapi: Core.Strapi): Promise<void> {
81	  const rows = (await strapi.db.query(UID).findMany({
82	    populate: { driverAgeBands: true, vehicleAgeBands: true },
83	  })) as unknown as Array<PricingRow & { id: number; documentId: string; publishedAt?: string | null }>;
84	  for (const row of rows) {
85	    const patch = pricingPatch(row);
86	    const keys = Object.keys(patch);
87	    if (keys.length === 0) continue;
88	    const bands = Object.fromEntries(keys.filter((k) => BAND_KEYS.includes(k)).map((k) => [k, patch[k]]));
89	    const scalars = Object.fromEntries(keys.filter((k) => !BAND_KEYS.includes(k)).map((k) => [k, patch[k]]));
90	    if (Object.keys(scalars).length > 0) {
91	      await strapi.db.query(UID).update({ where: { id: row.id }, data: scalars });
92	    }
93	    if (Object.keys(bands).length > 0) {
94	      await strapi.documents(UID).update({
95	        documentId: row.documentId,
96	        data: bands as never,
97	        status: row.publishedAt ? 'published' : 'draft',
98	      });
99	    }
100	  }
101	}
