103	async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
104	  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
105	  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
106	  const { size } = fs.statSync(filepath);
107	  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
108	    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
109	    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
110	  });
111	  return uploaded.id;
112	}
