114	export async function seedCountries(strapi: Core.Strapi): Promise<void> {
115	  const total = await strapi.documents(UID).count({});
116	  if (total > 0) return;
117	
118	  for (const country of COUNTRIES) {
119	    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
120	    await strapi.documents(UID).create({
121	      data: { code: country.code, name: country.name, order: country.order, active: country.active, legalAge: country.legalAge, currency: country.currency, numberLocale: country.numberLocale, driverAgeBands: DRIVER_BANDS, vehicleAgeBands: VEHICLE_BANDS, icon },
122	      status: 'published',
123	    });
124	  }
125	}
